#!/usr/bin/env python3
"""Build web/vendor/tabler-icons.svg from an installed @tabler/icons package.

Usage: python3 web/vendor/make-icon-sprite.py PATH/TO/node_modules/@tabler/icons
Add icons to ICONS below, then re-run. Only the listed icons are bundled.
"""
import json, re, sys
from pathlib import Path

# (sprite id, style, Tabler icon name)
ICONS = [
    ("play", "filled", "player-play"),
    ("pause", "filled", "player-pause"),
    ("skip", "filled", "player-skip-forward"),
    ("stop", "filled", "player-stop"),
    ("restart", "outline", "rotate-clockwise"),
    ("refresh", "outline", "refresh"),
    ("reload-settings", "outline", "file-download"),
    ("upload", "outline", "upload"),
    ("trash", "outline", "trash"),
    ("copy", "outline", "copy"),
    ("check", "outline", "check"),
    ("plus", "outline", "plus"),
    ("x", "outline", "x"),
]

package = Path(sys.argv[1] if len(sys.argv) > 1 else "node_modules/@tabler/icons")
version = json.loads((package / "package.json").read_text())["version"]
out = Path(__file__).with_name("tabler-icons.svg")
symbols = []
for sprite_id, style, name in ICONS:
    svg = (package / "icons" / style / f"{name}.svg").read_text()
    body = re.search(r"<svg[^>]*>(.*)</svg>", svg, re.S).group(1)
    # Drop Tabler's transparent bounding box and collapse whitespace.
    body = re.sub(r'<path stroke="none" d="M0 0h24v24H0z" fill="none"\s*/>', "", body)
    body = " ".join(body.split())
    paint = ('fill="currentColor"' if style == "filled" else
             'fill="none" stroke="currentColor" stroke-width="2" '
             'stroke-linecap="round" stroke-linejoin="round"')
    symbols.append(f'<symbol id="i-{sprite_id}" viewBox="0 0 24 24" {paint}>{body}</symbol>')
out.write_text(
    f"<!-- Tabler Icons v{version} (MIT, https://tabler.io/icons); generated by make-icon-sprite.py -->\n"
    '<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" '
    'style="position:absolute;width:0;height:0;overflow:hidden">\n'
    + "\n".join(symbols) + "\n</svg>\n"
)
print(f"Wrote {len(symbols)} icons to {out}")
